package collaborationrun
import("fmt";"strings";"testing";"github.com/multica-ai/multica/server/pkg/agent";"github.com/multica-ai/multica/server/pkg/protocol")
func TestFinalReviewInvalidChunkMustNotRebaseSuffix(t *testing.T){
 ledger:=newHostTestLedger(t);local:=registerHostTestRun(t,ledger);defer local.Close();hostTestPermit(t,local)
 supervisor:=&hostSupervisor{runner:&Runner{},local:local};record:=&hostRecording{}
 sender,err:=startHostCheckpoints(t.Context(),supervisor,record,1);if err!=nil{t.Fatal(err)}
 supervisor.mu.Lock()
 record.message(agent.Message{Type:agent.MessageToolUse,CallID:"call",Tool:strings.Repeat("n",129),Input:map[string]any{}},&HostActivity{})
 for i:=1;i<32;i++{record.add(protocol.CollaborationRecordedMessage{Kind:"message",Role:"assistant",Body:fmt.Sprintf("original-ordinal-%d",i)})}
 supervisor.mu.Unlock();sender.finish()
 rec:=local.record.Host.Recording
 for _,c:=range rec.Chunks{t.Logf("retained chunk seq=%d offset=%d count=%d first=%s",c.Sequence,c.Offset,c.Count,c.Payload.Messages[0].Body)}
 if len(rec.Chunks)>0{t.Fatal("later queued messages were staged after an irrecoverable first chunk rejection")}
}
